 settings:'<circle cx="12" cy="12" r="3"/><path d="M4 12l-1.5-2.5L5 6.5 8 7l2-3h4l2 3 3-.5 2.5 3L20 12l1.5 2.5-2.5 3-3-.5-2 3h-4l-2-3-3 .5-2.5-3L4 12z"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
